local function setFaceTexture(p1, p2) --[[ setFaceTexture | Line: 33 ]]
	p1:WaitForChild("Config")

	local BlinkingParts = p1:FindFirstChild("BlinkingParts")
	local list = {}

	if BlinkingParts and #BlinkingParts:GetChildren() > 0 then
		for i, v in ipairs(BlinkingParts:GetChildren()) do
			if v:IsA("ObjectValue") then
				table.insert(list, v.Value)

				if v.Value:FindFirstChildWhichIsA("MeshPart") then
					table.insert(list, v.Value:FindFirstChildWhichIsA("MeshPart"))
				end
			end
		end
	else
		local Head = p1:FindFirstChild("Head")

		if not Head then
			warn("No Head found in character and no BlinkingParts folder.")

			return
		end

		table.insert(list, Head)

		if Head:FindFirstChild("Head") then
			table.insert(list, Head.Head)
		end
	end

	for i, v in ipairs(list) do
		if v:IsA("MeshPart") then
			v.TextureID = p2
		end
	end
end

function t.HurtAnimation(p1) --[[ HurtAnimation | Line: 72 | Upvalues: setFaceTexture (copy) ]]
	local Config = p1:WaitForChild("Config")
	local v3 = Config:FindFirstChild((if p1:GetAttribute("Transformed") == true then "Transform" else "") .. "HurtTexture")

	if v3 then
		setFaceTexture(p1, v3.Texture)
	end

	task.wait(2)

	if p1.Parent == nil then
		return
	end

	local v6 = Config:FindFirstChild((if if p1:GetAttribute("Transformed") == true then true else false then "Transform" else "") .. "NormalTexture")

	if not v6 then
		return
	end

	setFaceTexture(p1, v6.Texture)
end

